    if(!account){toast('Почта входа не получена');return}if(!date){toast('Введите дату списания');return}const valid=()=>current(requestBinding)&&sameAccount(vendor,account,accountGen);billingSaving=true;dateJob={vendor,account,accountGen,rev};b.disabled=true;
